import{_ as o,l as s,o as e,c as n,v as t,p as l,x as r,d as E,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"形式等价检查","description":"","frontmatter":{"title":"形式等价检查","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/formal-equivalence.md","filePath":"cs/formal-equivalence.md","lastUpdated":1789023840000}'),h={name:"cs/formal-equivalence.md"};function p(A,a,B,m,T,_){const i=s("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="形式等价检查" tabindex="-1">形式等价检查 <a class="header-anchor" href="#形式等价检查" aria-label="Permalink to &quot;形式等价检查&quot;">​</a></h1><div class="epigraph"><p>综合可能改结构但不该改功能：等价检查把 RTL 与网表切成逻辑锥，用 SAT/BDDs 证明对应点相同，不依赖测试向量有没有打到。</p><footer>—— 据 Brand, Verification of Large Synthesized Designs, ICCAD 1993；IEEE Std 1800；Hennessy and Patterson 体系结构验证实践 整理</footer></div><p><a href="/cs/verification-testbench">上一课</a>的仿真会漏未覆盖状态。<a href="/cs/proof-assistants">证明助手</a>已展示「核检查」；数字流程里更常用的是<strong>组合/时序等价检查</strong>（LEC）：同一设计的两个视图是否功能相同。缺口是把这层签核接到综合网表，而不是再写 TB。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>综合优化、资源共享、FSM 编码可能改变中间节点。仿真回归成本随 NRE 涨。缺口：需要与向量无关的<strong>结构对应证明</strong>，把「工具没改功能」从「碰巧测过」里拆出来。</p><h3 id="等价不是「符合-ieee-754-规范」" tabindex="-1">等价不是「符合 IEEE 754 规范」 <a class="header-anchor" href="#等价不是「符合-ieee-754-规范」" aria-label="Permalink to &quot;等价不是「符合 IEEE 754 规范」&quot;">​</a></h3><p>两边都错会显示等价。规范符合性仍靠 TB、断言或更高层形式（属性检查）。把 LEC 通过当成 FMA 正确舍入的证明，黄金模型从未出场。</p><p><span class="marginnote">Brand, ICCAD 1993 是组合等价的经典工业问题表述。现代工具用 SAT。本课不发明 arXiv。属性检查（model checking）在计算理论补层的<a href="/cs/model-checking">模型检验</a>已给直觉，这里用在网表签核。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对应点：RTL 寄存器与网表 FF，由名称或映射文件配对。每个组合锥：从输入与寄存器 Q 到下一状态 D 与输出。证明两锥布尔等价。失败：给出反例向量，可送回仿真。时钟门控、扫描插入、流水线重定时会改寄存器边界，必须告诉工具「这些变换合法」，否则误报。</p><p>时序等价（retimed）更难，本课以组合锥+寄存器映射为主。</p>',11)),(e(),l(c,null,{default:r(()=>[d(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20RTL%5B%22RTL%22%5D%20--%3E%20CONE%5B%22%E5%AF%84%E5%AD%98%E5%99%A8%E6%98%A0%E5%B0%84%E4%B8%8E%E9%80%BB%E8%BE%91%E9%94%A5%22%5D%0A%20%20NL%5B%22%E7%BB%BC%E5%90%88%E7%BD%91%E8%A1%A8%22%5D%20--%3E%20CONE%0A%20%20CONE%20--%3E%20SAT%5B%22SAT%20%2F%20BDD%20%E7%AD%89%E4%BB%B7%22%5D%0A%20%20SAT%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%A1%85%E4%B8%8A%E8%BF%98%E8%A6%81%E5%8F%AF%E6%B5%8B%E6%80%A7%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>DFT 插入扫描 MUX 后要再跑一遍 LEC，或把扫描使能当约束常数做功能模式等价。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课扫描链改变了 FF 的 D 输入（测试 MUX）。BIST 再加模式。每次网表变换后等价检查是物理设计的闸门。CDC 结构（格雷指针）的功能正确性通常仍靠仿真/断言，LEC 只保证实现视图一致。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把完整芯片当定理证明作业，不写 SAT 求解器内部。不把模拟电路等价（SPICE vs Verilog-A）算进来。不重开依值类型。</p><p>后课默认：RTL↔网表用等价检查签核功能不变；规范正确性仍要 TB；扫描插入后再比一次。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LEC 证两视图逻辑锥相同，不靠覆盖率。</li><li>两边同错仍等价；规范靠其他手段。</li><li>门控、扫描、重定时须建模为合法变换。</li><li>出处：Brand, ICCAD 1993；IEEE 1800；与模型检验课衔接。</li></ul>',8))])}const C=o(h,[["render",p]]);export{u as __pageData,C as default};
